const { signAccessToken, signRefreshToken, verifyRefreshToken } = require('./tokens');
const users = require('../users/repository');

async function login(req, res, next) {
  try {
    const { email, password } = req.body;
    const user = await users.findByEmail(email);

    if (!user || !(await users.verifyPassword(user, password))) {
      return res.status(401).json({ error: 'invalid credentials' });
    }

    const payload = { sub: user.id, email: user.email };
    return res.json({
      accessToken: signAccessToken(payload),
      refreshToken: signRefreshToken(payload),
    });
  } catch (err) {
    return next(err);
  }
}

async function refresh(req, res, next) {
  try {
    const { refreshToken } = req.body;

    if (!refreshToken) {
      return res.status(400).json({ error: 'refreshToken is required' });
    }

    const payload = verifyRefreshToken(refreshToken);
    const user = await users.findById(payload.sub);

    if (!user) {
      return res.status(401).json({ error: 'invalid refresh token' });
    }

    const nextPayload = { sub: user.id, email: user.email };
    return res.json({
      accessToken: signAccessToken(nextPayload),
      refreshToken: signRefreshToken(nextPayload),
    });
  } catch (err) {
    return next(err);
  }
}

module.exports = {
  login,
  refresh,
};
